       // self (MyViewController) \u6301\u6709 dataManager\n        // dataManager \u7684 onDataUpdate \u95ED\u5305\u6355\u83B7\u4E86 self (MyViewController)\n        // \u5982\u679C\u95ED\u5305\u662F\u5F3A\u5F15\u7528 self\uFF0C\u5C31\u5F62\u6210\u4E86\u5FAA\u73AF\uFF1Aself -> dataManager -> onDataUpdate -> self\n        // dataManager.onDataUpdate = {\n        //     // \u5728\u9003\u9038\u95ED\u5305\u4E2D\u9690\u5F0F\u5F15\u7528 self (\u867D\u7136\u63A8\u8350\u663E\u5F0F\u5199 self.)\n        //     // \u5982\u679C\u4E0D\u5199 [weak self]\uFF0C\u8FD9\u91CC\u4F1A\u5F3A\u5F15\u7528 MyViewController\n        //     print("MyViewController: DataManager \u6570\u636E\u5DF2\u66F4\u65B0 - \\(self.dataManager.data)")\n        //     self.updateUI() // \u9690\u5F0F\u5F15\u7528 self\n        // }\n\n        // --- \u4F7F\u7528 [weak self] \u6253\u7834\u5FAA\u73AF\u5F15\u7528 ---\n        dataManager.onDataUpdate = { [weak self] in\n            guard let strongSelf = self else { return } // \u68C0\u67E5 self \u662F\u5426\u5B58\u5728\n            print("MyViewController (Safe): DataManager \u6570\u636E\u5DF2\u66F4\u65B0 - \\(strongSelf.dataManager.data)")\n            strongSelf.updateUI() // \u4F7F\u7528 strongSelf\n        }\n\n        // dataManager.loadDataAsync() // \u53EF\u80FD\u5BFC\u81F4\u5FAA\u73AF\u5F15\u7528\uFF08\u5982\u679C onDataUpdate \u5F3A\u5F15\u7528 self\uFF09\n        dataManager.loadDataAsyncSafe() // \u4F7F\u7528\u4E86 [weak self]\uFF0C\u66F4\u5B89\u5168\n    }\n\n    func updateUI() {\n        print("MyViewController: \u66F4\u65B0 UI...")\n    }\n\n    deinit {\n        print("MyViewController deinitialized")\n    }\n}\n\nprint("\\n--- \u5FAA\u73AF\u5F15\u7528\u6D4B\u8BD5 ---")\nvar viewController: MyViewController? = MyViewController()\nviewController?.viewDidLoad()\n\n// \u8BBE\u7F6E\u4E3A nil\uFF0C\u89E6\u53D1 deinit (\u5982\u679C\u6CA1\u6709\u5FAA\u73AF\u5F15\u7528)\nprint("\\n\u8BBE\u7F6E viewController \u4E3A nil...")\nviewController = nil\n// \u5