re: Double = Double.nan // \u521D\u59CB\u65E0\u6548\u503C\n    private var measurements: [Double] = [] // \u9694\u79BB\u7684\u72B6\u6001\n\n    init(id: String) {\n        self.id = id\n        print("Actor Sensor \\(id) init")\n    }\n\n    // Actor \u5185\u90E8\u53EF\u4EE5\u540C\u6B65\u8BBF\u95EE\u81EA\u5DF1\u7684\u72B6\u6001\n    func recordMeasurement(_ temp: Double) {\n        currentTemperature = temp\n        measurements.append(temp)\n        print("Actor Sensor \\(id): \u8BB0\u5F55\u6E29\u5EA6 \\(temp)")\n    }\n\n    // \u5916\u90E8\u8C03\u7528\u8FD9\u4E2A\u65B9\u6CD5\u9700\u8981 await\n    func getAverageTemperature() -> Double {\n        guard !measurements.isEmpty else { return Double.nan }\n        let sum = measurements.reduce(0, +)\n        let avg = sum / Double(measurements.count)\n        print("Actor Sensor \\(id): \u8BA1\u7B97\u5E73\u5747\u6E29\u5EA6 \\(avg)")\n        return avg\n    }\n\n    // nonisolated \u5C5E\u6027\u53EF\u4EE5\u540C\u6B65\u8BBF\u95EE (\u901A\u5E38\u662F\u5E38\u91CF)\n    nonisolated let unit = "Celsius"\n\n    // nonisolated \u65B9\u6CD5\u53EF\u4EE5\u540C\u6B65\u8C03\u7528\uFF0C\u4F46\u4E0D\u80FD\u8BBF\u95EE\u9694\u79BB\u72B6\u6001\n    nonisolated func describeUnit() {\n        print("Actor Sensor \\(id): \u6E29\u5EA6\u5355\u4F4D\u662F \\(unit)")\n        // print(currentTemperature) // \u9519\u8BEF: Actor-isolated property \'currentTemperature\' can not be referenced from a non-isolated context\n    }\n\n    deinit {\n        print("Actor Sensor \\(id) deinit")\n    }\n}\n\nprint("\\n--- Actor \u793A\u4F8B ---")\nlet sensor1 = TemperatureSensor(id: "A")\nlet sensor2 = TemperatureSensor(id: "B")\n\n// \u4F7F\u7528 Task \u5E76\u53D1\u8BBF\u95EE Actor\nTask {\n    print("Task 1: \u51C6\u5907\u8BBF\u95EE Sensor A")\n    // \u8BBF\u95EE Actor \u7684\u65B9\u6CD5\u9700\u8981 await\n    await sensor1.recordMeasurement(25.5)\n    await sensor1.recordMeasurement(26.0)\n    let avgA = await sensor1.getAverageTemperature()\n    print("Task 1: Sensor A \u5E73\u5747\u6E29\u5EA6 \\(avgA)")\n\n    // \u8BBF\u95EE nonisolated \u6210\u5458\u4E0D\u9700\u8981 await\n    print("Task 1: Sensor A \u5355\u4F4D: \\(sensor1.unit)")\n    sensor1.describeUnit()\n}\n\nTask {\n    print("Task 2: \u51C6\u5907\u8BBF\u95EE Sensor B \u548C A")\n    await sensor2.recordMeasurement(10.0)\n    await sensor1.recordMeasurement(25.8) // \u4E0E Task 1 \u7684\u8BBF\u95EE\u4F1A\u81EA\u52A8\u534F\u8C03\uFF0C\u4E0D\u4F1A\u51B2\u7A81\n    let avgB = await sensor2.getAverageTemperature()\n    print("Task 2: Sensor B \u5E73\u5747\u6E29\u5EA6 \\(avgB)")\n    let avgA_again = await sensor1.getAverageTemperature()\n     print("Task 2: Sensor A \u5E73\u5747\u6E29\u5EA6 (\u518D\u6B21\u83B7\u53D6) \\(avgA_again)")\n}\n\n\n// --- @MainActor \u793A\u4F8B ---\nclass MyViewModel { // \u666E\u901A\u7C7B\n    var statusMessage = "Idle"\n\n    // \u6807\u8BB0\u8FD9\u4E2A\u65B9\u6CD5\u5728\u4E3B Actor (\u4E3B\u7EBF\u7A0B) \u4E0A\u6267\u884C\n    @MainActor\n    func updateStatus(_ message: String) async {\n        // \u786E\u4FDD\u5728\u4E3B\u7EBF\u7A0B\u6267\u884C\n        print("ViewModel: \u66F4\u65B0\u72B6\u6001 \'\\(message)\' on Main Thread? \\(Thread.isMainThread)")\n        statusMessage = message\n        // \u5728\u8FD9\u91CC\u53EF\u4EE5\u5B89\u5168\u5730\u66F4\u65B0 UI\n        // e.g., statusLabel.text = statusMessage\n    }\n\n    func performBackgroundWork() {\n        Task { // \u542F\u52A8\u540E\u53F0 Task\n            print("ViewModel: \u540E\u53F0\u4EFB\u52A1\u5F00\u59CB - \u7EBF\u7A0B: \\(Thread.current)")\n            await Task.sleep(nanoseconds: 500_000_000) // \u6A21\u62DF\u5DE5\u4F5C\n            let result = "\u5DE5\u4F5C\u5B8C\u6210"\n            print("ViewModel: \u540E\u53F0\u4EFB\u52A1\u5B8C\u6210")\n\n            // \u9700\u8981\u56DE\u5230\u4E3B\u7EBF\u7A0B\u66F4\u65B0\u72B6\u6001/UI\n            // \u8C03\u7528 @MainActor \u65B9\u6CD5\u4F1A\u81EA\u52A8\u5207\u6362\n            await updateStatus(result)\n      